     1	(* Find local alignment ranges with a rolling-row Smith-Waterman recurrence. *)
     2	
     3	open Printf
     4	
     5	type config = { score : char -> char -> int; gap : char -> int }
     6	
     7	let code =
     8	  {
     9	    score = (fun a b -> if a = b then 2 else -2);
    10	    gap =
    11	      (function
    12	      | ' '
    13	      | '\t'
    14	      | '\r'
    15	      | '\n' ->
    16	          0
    17	      | _ -> 1);
    18	  }
    19	
    20	type range = { start : int; end_ : int }
    21	
    22	type alignment = {
    23	  query : range;
    24	  target : range;
    25	  score : int;
    26	  identical_bytes : int;
    27	}
    28	
    29	let show_range x = sprintf "[%d,%d)" x.start x.end_
    30	let equal_range = ( = )
