    32	let align { score; gap } query target =
    33	  let n = String.length target in
    34	  let previous = ref (Array.make (n + 1) 0) in
    35	  let current = ref (Array.make (n + 1) 0) in
    36	  (* Carry start coordinates with each score instead of storing a traceback
    37	     matrix. Only the previous and current rows are needed. *)
    38	  let previous_query_start = ref (Array.make (n + 1) 0) in
    39	  let current_query_start = ref (Array.make (n + 1) 0) in
    40	  let previous_target_start = ref (Array.make (n + 1) 0) in
    41	  let current_target_start = ref (Array.make (n + 1) 0) in
    42	  let previous_identical = ref (Array.make (n + 1) 0) in
    43	  let current_identical = ref (Array.make (n + 1) 0) in
    44	  let query_gaps =
    45	    Array.init (String.length query) (fun i -> gap query.[i])
    46	  in
    47	  let target_gaps =
    48	    Array.init (String.length target) (fun i -> gap target.[i])
    49	  in
    50	  if Array.exists (( > ) 0) query_gaps || Array.exists (( > ) 0) target_gaps
    51	  then invalid_arg "Smith_waterman.align: negative gap penalty";
    52	  let best_score = ref 0 in
    53	  let best = ref None in
    54	  let swap a b =
    55	    let old = !a in
    56	    a := !b;
    57	    b := old
    58	  in
    59	  for i = 1 to String.length query do
    60	    !current.(0) <- 0;
    61	    !current_identical.(0) <- 0;
    62	    for j = 1 to n do
    63	      let value = ref 0 in
    64	      let query_start = ref (i - 1) in
    65	      let target_start = ref (j - 1) in
    66	      let identical = ref 0 in
    67	      let consider candidate row col source_query source_target count =
    68	        if candidate > !value then begin
    69	          value := candidate;
    70	          identical := count;
    71	          query_start := source_query.(col);
    72	          target_start := source_target.(col);
    73	          if row.(col) = 0 then begin
    74	            query_start := i - 1;
    75	            target_start := j - 1
    76	          end
    77	        end
    78	      in
    79	      consider
    80	        (!previous.(j - 1) + score query.[i - 1] target.[j - 1])
    81	        !previous (j - 1) !previous_query_start !previous_target_start
    82	        (!previous_identical.(j - 1)
    83	        + if query.[i - 1] = target.[j - 1] then 1 else 0);
    84	      consider
    85	        (!previous.(j) - query_gaps.(i - 1))
    86	        !previous j !previous_query_start !previous_target_start
    87	        !previous_identical.(j);
    88	      consider
    89	        (!current.(j - 1) - target_gaps.(j - 1))
    90	        !current (j - 1) !current_query_start !current_target_start
    91	        !current_identical.(j - 1);
    92	      !current.(j) <- !value;
    93	      !current_identical.(j) <- !identical;
    94	      !current_query_start.(j) <- !query_start;
    95	      !current_target_start.(j) <- !target_start;
    96	      if !value > !best_score then begin
    97	        best_score := !value;
    98	        best :=
    99	          Some
   100	            {
   101	              query = { start = !query_start; end_ = i };
   102	              target = { start = !target_start; end_ = j };
   103	              score = !value;
   104	              identical_bytes = !identical;
   105	            }
   106	      end
   107	    done;
   108	    swap previous current;
   109	    swap previous_query_start current_query_start;
   110	    swap previous_target_start current_target_start;
   111	    swap previous_identical current_identical
   112	  done;
   113	  !best
